        i = 0
        while i < len(coords):
            r, c = coords[i]
            color = grid[r][c]
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < len(coords) and grid[coords[j][0]][coords[j][1]] == color:
                j += 1
            if j-i >= 2:
                starts.extend((coords[k][0], coords[k][1], dr, dc, color) for k in range(i, j))
            i = j
    add_runs([(0,c) for c in range(w)], 1, 0)
    add_runs([(h-1,c) for c in range(w)], -1, 0)
    add_runs([(r,0) for r in range(h)], 0, 1)
    add_runs([(r,w-1) for r in range(h)], 0, -1)

    for r,c,dr,dc,color in starts:
        rr,cc=r+dr,c+dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == marker:
                out[rr][cc] = 4
                break
            if grid[rr][cc] != bg:
                break
            out[rr][cc] = marker
            rr += dr; cc += dc

