 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Edge-connected bars act as a mask: they expose/fill their inward
    # rectangular projection with the sparse interior color. The sparse
    # singleton markers are recolored 4; bar/marker colors vary by instance.
    colors = [v for v in counts if v != bg]
    sparse = min(colors, key=lambda v: counts[v])
    # Distinct interior marker color typically has several instances and lies
    # between the bar and background frequencies; use the color of the lone
    # interior object when there is one.
    interior = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
                if grid[r][c] != bg and r not in (0,h-1) and c not in (0,w-1)]
    interior_colors = {v for _,_,v in interior}
    if len(interior_colors) == 1:
        paint = next(iter(interior_colors))
    else:
        paint = sparse

    # Solid edge stripes on the top/right/bottom/left point inward along rows
    # or columns. Use only cells in the stripe's span; rays stop at matching
    # interior marker pixels (which turn to 4) or other foreground objects.
    rays=[]
    for c in range(w):
        if grid[0][c] != bg: rays.append((0,c,1,0))
        if grid[h-1][c] != bg: rays.append((h-1,c,-1,0))
    for r in range(h):
        if grid[r][0] != bg: rays.append((r,0,0,1))
        if grid[r][w-1] != bg: rays.append((r,w-1,0,-1))
    for r,c,dr,dc in rays:
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w:
            if grid[rr][cc] == paint:
                out[rr][cc]=4
                break
            if grid[rr][cc] != bg:
                break
            out[rr][cc]=paint
            rr+=dr;cc+=dc
    return out

