    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    # Isolated interior color is the ray color; single-cell hits become 4.
    marker_color = min((v for v in counts if v != bg), key=lambda v: counts[v])
    targets = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker_color and 0 < r < h-1 and 0 < c < w-1]

    # Perimeter bars launch rays inward along their perpendicular axis. The
    # ray fills with the interior marker color and stops at its matching marker,
    # which is changed to 4. A marker is processed only when it is aligned with
    # an edge bar, as illustrated by the row/column projections in the examples.
    top = {c for c in range(w) if grid[0][c] != bg}
    bottom = {c for c in range(w) if grid[h-1][c] != bg}
    left = {r for r in range(h) if grid[r][0] != bg}
    right = {r for r in range(h) if grid[r][w-1] != bg}
    for r, c in targets:
        if c in top:
            for rr in range(1, r):
                if grid[rr][c] == bg:
                    out[rr][c] = marker_color
            out[r][c] = 4
        elif c in bottom:
            for rr in range(r+1, h-1):
                if grid[rr][c] == bg:
                    out[rr][c] = marker_color
            out[r][c] = 4
        elif r in left:
            for cc in range(1, c):
                if grid[r][cc] == bg:
                    out[r][cc] = marker_color
            out[r][c] = 4
        elif r in right:
            for cc in range(c+1, w-1):
                if grid[r][cc] == bg:
                    out[r][cc] = marker_color
            out[r][c] = 4
    return out

